# Fixing solve_linear_system in linalg.py by correcting pivot normalization to iterate c from i to n inclusive (was from i to n+1)
# And also correct gauss_jordan_inverse: divide augmented[i][j] for j in range 2*n, not i*2 to 2*n (wrong indexing)
sed -i '/def solve_linear_system(A: Matrix, b: Vector) -> Vector:/,/return \\[augmented\[i\]\[n\] for i in range(n)\]/{s/for c in range(i, n+1):/for c in range(i, n+1):/g}' /work/linalg.py
sed -i '/def gauss_jordan_inverse(matrix: Matrix) -> Matrix:/,/return inverse/{
/^        # Normalize pivot row$/a\
        # Normalize pivot row
        for j in range(2*n):
            augmented[i][j] /= pivot
        next
}' /work/l
